<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Balls in Rotating Hexagon</title>
<style>body{margin:0;overflow:hidden;background:#222}</style>
</head>
<body>
<canvas id="canvas"></canvas>
<script>
const canvas=document.getElementById('canvas'),ctx=canvas.getContext('2d');
let W, H;
function resize(){
    W=canvas.width=window.innerWidth;
    H=canvas.height=window.innerHeight;
}
window.addEventListener('resize',resize);
resize();

const center={x:W/2,y:H/2};
const hexRadius=200;           // distance from center to hexagon vertex
const hexSides=6;
const rotationSpeed=0.002;     // radians per frame
let rotation=0;

const gravity=0.2;             // pixels per frame^2
const friction=0.999;          // velocity decay factor
const restitution=0.95;        // bounciness
const balls=[];
const ballCount=10;

// Utility functions
function randRange(min,max){return Math.random()*(max-min)+min;}
function randomColor(){return 'hsl('+Math.random()*360+',70%,50%)';}
function normalize(v){const l=Math.hypot(v.x,v.y);return {x:v.x/l,y:v.y/l};}
function dot(a,b){return a.x*b.x+a.y*b.y;}
function length(v){return Math.hypot(v.x,v.y);}
function add(a,b){return {x:a.x+b.x,y:a.y+b.y};}
function sub(a,b){return {x:a.x-b.x,y:a.y-b.y};}
function mul(v,s){return {x:v.x*s,y:v.y*s};}
function pointInPolygon(pt,poly){
    let inside=false, n=poly.length;
    for(let i=0,j=n-1;i<n;j=i++){
        const pi=poly[i], pj=poly[j];
        const intersect=((pi.y>pt.y)!=(pj.y>pt.y)) &&
                         (pt.x<(pj.x-pi.x)*(pt.y-pi.y)/(pj.y-pi.y)+pi.x);
        if(intersect) inside=!inside;
    }
    return inside;
}

// Compute hexagon vertices for current rotation
function getHexVertices(){
    const verts=[];
    for(let i=0;i<hexSides;i++){
        const angle=Math.PI/3*i+rotation;
        verts.push({
            x:center.x+hexRadius*Math.cos(angle),
            y:center.y+hexRadius*Math.sin(angle)
        });
    }
    return verts;
}

// Ball constructor
class Ball{
    constructor(){
        this.r=randRange(15,25);
        // Find random point inside hexagon
        while(true){
            const x=randRange(center.x-hexRadius,center.x+hexRadius);
            const y=randRange(center.y-hexRadius,center.y+hexRadius);
            const pt={x,y};
            const verts=getHexVertices();
            if(pointInPolygon(pt,verts)){
                this.pos=pt;break;
            }
        }
        this.vel={x:randRange(-2,2),y:randRange(-2,2)};
        this.color=randomColor();
    }
    update(){
        this.vel.y+=gravity;            // gravity
        this.vel.x*=friction;           // horizontal friction
        this.vel.y*=friction;           // vertical friction
        this.pos.x+=this.vel.x;
        this.pos.y+=this.vel.y;
    }
    draw(){
        ctx.beginPath();
        ctx.arc(this.pos.x,this.pos.y,this.r,0,2*Math.PI);
        ctx.fillStyle=this.color;
        ctx.fill();
    }
}
for(let i=0;i<ballCount;i++) balls.push(new Ball());

// Collision between two balls
function ballBallCollision(a,b){
    const diff=sub(b.pos,a.pos);
    const dist=length(diff);
    const sumR=a.r+b.r;
    if(dist<sumR){
        const normal=normalize(diff);
        const relVel=sub(b.vel,a.vel);
        const relVelAlongNormal=dot(relVel,normal);
        if(relVelAlongNormal<0){ // moving towards each other
            const j=-(1+restitution)*relVelAlongNormal/(1+1); // masses equal
            const impulse=mul(normal,j);
            a.vel=add(a.vel,mul(impulse,1));
            b.vel=sub(b.vel,mul(impulse,1));
        }
        // Resolve interpenetration
        const overlap=sumR-dist;
        const move=mul(normal,overlap/2);
        a.pos=sub(a.pos,move);
        b.pos=add(b.pos,move);
    }
}

// Collision between ball and hexagon wall
function ballHexCollision(ball,verts){
    const n=verts.length;
    for(let i=0;i<n;i++){
        const v1=verts[i], v2=verts[(i+1)%n];
        const segDir=sub(v2,v1);
        const segLen=length(segDir);
        const segNorm=normalize({x:-segDir.y, y:segDir.x}); // outward normal
        const toBall=sub(ball.pos,v1);
        const proj=dot(toBall,segNorm);
        if(proj>0 && proj<ball.r) return; // inside polygon, no collision
        const closest=dot(toBall,normalize(segDir));
        const distToSeg= (closest<0)? length(toBall):
                         (closest>segLen)? length(sub(ball.pos,v2)):
                         Math.abs(dot(toBall,segNorm));
        if(distToSeg<ball.r){
            // Normal should point from wall to ball
            const normal=segNorm;
            // Reflect velocity
            const vDotN=dot(ball.vel,normal);
            ball.vel=sub(ball.vel,mul(normal,(1+restitution)*vDotN));
            // Push ball out of penetration
            const overlap=ball.r-distToSeg;
            ball.pos=add(ball.pos,mul(normal,overlap+0.01));
        }
    }
}

function animate(){
    rotation+=rotationSpeed;
    const verts=getHexVertices();

    // Update physics
    for(const ball of balls) ball.update();
    // Ball-ball collisions
    for(let i=0;i<balls.length;i++){
        for(let j=i+1;j<balls.length;j++) ballBallCollision(balls[i],balls[j]);
    }
    // Ball-hex collisions
    for(const ball of balls) ballHexCollision(ball,verts);

    // Draw
    ctx.fillStyle='#222';
    ctx.fillRect(0,0,W,H);

    // Draw hexagon
    ctx.beginPath();
    ctx.moveTo(verts[0].x,verts[0].y);
    for(let i=1;i<verts.length;i++) ctx.lineTo(verts[i].x,verts[i].y);
    ctx.closePath();
    ctx.lineWidth=4;
    ctx.strokeStyle='white';
    ctx.stroke();

    // Draw balls
    for(const ball of balls) ball.draw();

    requestAnimationFrame(animate);
}
requestAnimationFrame(animate);
</script>
</body>
</html>
```
This script simulates 10 balls affected by gravity, friction, and realistic collisions inside a slowly spinning hexagon using basic physics and canvas rendering.
